bool TelemetryBuffer::pop(Sample& out) {
    __disable_irq();
    if (tail == head) {
        __enable_irq();
        return false;
    }
    out = slots[tail];
    tail = (tail + 1) & 0x0f;
    __enable_irq();
    return true;
}
