                .into(object : SimpleTarget<Bitmap>() {
                    override fun onResourceReady(resource: Bitmap, transition: Transition<in Bitmap>?) {
                        val enhancedBitmap = upscaleImage(resource, 2.0)
                        imageView.setImageBitmap(enhancedBitmap)

// Scale down the bitmap to prevent “Canvas: trying to draw too large bitmap” error
                        val scaledDownBitmap = Bitmap.createScaledBitmap(enhancedBitmap, imageView.width, imageView.height, false)
                        imageView.setImageBitmap(scaledDownBitmap)
                    }
                })
        }
