                System.out.print("Player call, state bet: ");
                bet = input.nextInt();
            } else {
                System.out.println("Dealer call, state bet: ");
                bet = (int) (Math.random() * (chips / 2) + 1);
                System.out.println(bet);
            }

            // Update chips
            chips -= bet;
            System.out.println(username + ", You are left with " + chips + " chips");
            System.out.println("Bet on table : " + (bet * 2));
            System.out.println("================================================================================");

            roundNumber++;
        }
    }
}

